<script setup lang="ts">import { ref } from 'vue'; import { UploadCloud } from 'lucide-vue-next'; import { formatBytes } from '../../utils/formatDate'; import { validarPDF, validarTamanho } from '../../utils/validators'; const emit = defineEmits<{ select: [file: File]; error: [message: string] }>(); const dragging = ref(false); function choose(file?: File) { if (!file) return; if (!validarPDF(file)) return emit('error', 'Selecione um arquivo PDF válido.'); if (!validarTamanho(file)) return emit('error', 'O arquivo deve ter no máximo 20 MB.'); emit('select', file) } </script>
<template><label class="flex cursor-pointer flex-col items-center justify-center rounded-xl border-2 border-dashed border-slate-300 bg-slate-50 p-10 text-center hover:border-primary" :class="{ 'border-primary bg-blue-50': dragging }" @dragover.prevent="dragging = true" @dragleave="dragging = false" @drop.prevent="dragging = false; choose($event.dataTransfer?.files[0])"><UploadCloud class="mb-3 h-10 w-10 text-primary" aria-hidden="true" /><span class="font-semibold">Arraste seu PDF ou clique para selecionar</span><span class="mt-1 text-sm text-slate-500">PDF até 20 MB</span><input class="sr-only" type="file" accept="application/pdf,.pdf" @change="choose(($event.target as HTMLInputElement).files?.[0])" /></label></template>
